/** The variable a sensitive or empty required argument becomes. */
function variableName(path                   )         {
  const name = path.join('_').replace(/[^A-Za-z0-9_]/g, '_');
  // Terraform reserves these for module blocks; `variable "source"` is an error.
  return RESERVED_VARIABLES.has(name) ? `${name}_value` : name;
}

const RESERVED_VARIABLES = new Set(['source', 'version', 'providers', 'count', 'for_each', 'lifecycle', 'depends_on', 'locals']);

function attrInput(
  row         ,
  path                   ,
  section                    ,
  showWhen                            ,
)                 {
  const [name, type, flags, description, values] = row;
  const required = flags.startsWith('r');
  const sensitive = flags.includes('s');
  const id = `r.${[...path, name].join('.')}`;
  const hintParts = [TYPE_HINT[type], required ? 'required' : flags.startsWith('c') ? 'optional — provider picks a default' : 'optional']
    .filter(Boolean);
  const base = {
    id,
    label: name,
    hint: hintParts.join(' · '),
    ...(description ? { help: description } : {}),
    ...(section ? { section } : {}),
    ...(showWhen ? { showWhen } : {}),
  };
  if (sensitive) {
    // Never a secret typed into a box that ends up in a file.
    const variable = variableName([...path, name]);
    return { ...base, control: 'text', default: required ? `var.${variable}` : '', placeholder: `var.${variable}`, hint: `${base.hint} · sensitive: use a var. reference` };
  }
  if (type === 'b') {
    return required
      ? { ...base, control: 'select', options: TRUE_FALSE, default: 'false' }
      : { ...base, control: 'select', options: TRUE_FALSE, blankLabel: '(provider default)' };
  }
  if (type === 'n') return { ...base, control: 'number', default: '' };
  if (type === 'h') {
    return { ...base, control: 'textarea', default: '', placeholder: `${name} {\n  ...\n}` };
  }
  if (type === 'm' || type === 'x') {
    return { ...base, control: 'textarea', default: '', placeholder: type === 'm' ? 'key = value' : '[{ ... }]' };
  }
  if (values && values.length > 0) {
    return {
      ...base,
      control: 'combo',
      options: values.map((v) => ({ value: v, label: v })),
      ...(required ? { default: '' } : { blankLabel: '(provider default)' }),
    };
  }
  return { ...base, control: 'text', default: '' };
}

function sectionName(path                   )         {
  return `Block: ${path.join(' › ')}`;
}

/**
 * Walk a block, producing its inputs in form order: this block's own
 * arguments, then each nested block's toggle and arguments.
 */
function blockInputs(
  block             ,
  path                   ,
  section                    ,
  gate                            ,
  out                  ,
)       {
  for (const row of block.a) {
    // Top level: required up top, optional in its section.
    const where = path.length === 0 ? (row[2].startsWith('r') ? undefined : OPTIONAL_SECTION) : section;
    out.push(attrInput(row, path, where, gate));
  }
  for (const [name, mode, min, max, child] of block.b ?? []) {
    const childPath = [...path, name];
    const childSection = sectionName(childPath);
    let childGate = gate;
    if (min < 1) {
      const toggle = `b.${childPath.join('.')}`;
      const many = mode !== 1 && max !== 1;
      out.push({
        id: toggle,
        label: `Include ${name}`,
        control: 'toggle',
        default: false,
        hint: many ? `nested block · repeatable${max > 1 ? `, up to ${max}` : ''} — repeat it in main.tf for more` : 'nested block',
        section: childSection,
        ...(gate ? { showWhen: gate } : {}),
      });
      childGate = { input: toggle, equals: ['true'] };
    }
    blockInputs(child, childPath, childSection, childGate, out);
  }
}

export function providerInputs(provider                )                   {
  const meta = PROVIDER_META[provider];
  if (meta.custom) return [...meta.custom.inputs];
  const credentialAttrs = new Set(meta.credentials.map((c) => c.attr));
  const inputs                   = [];
  const rows = [...info(provider).provider.a].sort((x, y) => {
    const dx = x[0] in meta.defaults ? 0 : 1;
    const dy = y[0] in meta.defaults ? 0 : 1;
    return dx - dy;
  });
  for (const row of rows) {
    const [name, , flags] = row;
    // Credentials and anything else sensitive stay out of the form entirely.
    if (credentialAttrs.has(name) || flags.includes('s') || /password|token|secret|_key$|client_auth_key/.test(name)) continue;
    if (meta.hide?.test(name)) continue;
    const { blankLabel, ...input } = attrInput(row, [], PROVIDER_SECTION, undefined);
    const preset = meta.defaults[name];
    inputs.push(
      preset === undefined
        ? { ...input, id: `p.${name}`, ...(blankLabel !== undefined ? { blankLabel } : {}) }
        : { ...input, id: `p.${name}`, default: String(preset) },
    );
  }
  return inputs;
}

// ------------------------------------------------------------------- HCL ---

/** A value that is an expression, not text: written without quotes. */
export function isExpression(value        )          {
  const v = value.trim();
  return (
    /^(var|local|data|module|each|count|path|terraform)\.[\w.\-[\]"*]+$/.test(v) ||
    /^[a-z][a-z0-9]*_[a-z0-9_]+\.[A-Za-z_][\w-]*(\[[^\]]+\])?\.[\w.[\]"*]+$/.test(v) ||
    /^[a-z][a-z0-9_]*\([\s\S]*\)$/.test(v) ||
    /^<<-?[A-Z]+\n[\s\S]*\n\s*[A-Z]+$/.test(v) ||
    /^(null|true|false)$/.test(v)
  );
}

function hclKey(key        )         {
  return /^[A-Za-z_][\w-]*$/.test(key) ? key : quote(key);
}

function indentRaw(text        , indent        )         {
  return text
    .trim()
    .split('\n')
    .map((line, i) => (i === 0 ? line : `${indent}${line}`))
    .join('\n');
}

                          
                                                                                             
                               
 

export function newEmitted()          {
  return { variables: new Map(), findings: [] };
}

function renderAttr(row         , raw         , path                   , indent        , out         )                {
  const [name, type, flags, description] = row;
  const required = flags.startsWith('r');
  let value = raw === undefined || raw === null ? '' : String(raw).trim();
  if (type === 'h') {
    // A nested block too deep for the form: whatever HCL was written, as written.
    if (value !== '') return indentRaw(`${indent}${value}`, indent).replace(/^\s*/, indent);
    if (required) out.findings.push(warning('terraform.schema.block-needed', `${[...path, name].join('.')} is a required block; write it in its HCL box.`, { path: [...path, name].join('.') }));
    return required ? `${indent}# ${name} { ... } is required: write it in its HCL box.` : null;
  }
  if (value === '') {
    if (!required) return null;
    // Required and not given: a variable, so the file plans once tfvars has it.
    value = `var.${variableName([...path, name])}`;
  }
  const varRef = /^var\.([A-Za-z_][\w-]*)$/.exec(value);
  if (varRef) {
    const variable = varRef[1]          ;
    if (!out.variables.has(variable)) {
      out.variables.set(variable, { type: VAR_TYPE[type], sensitive: flags.includes('s'), description: description || `${[...path, name].join('.')}` });
    }
  }
  const lhs = `${indent}${name} = `;
  const list = type === 'ls' || type === 'ss' || type === 'ln' || type === 'sn';
  // In a list field, `data.x.y.path` is one element; `var.x` or a function
  // call may well be the whole list, so those are left as they are.
  if (isExpression(value) && !(list && !/^(var|local)\.|^[a-z][a-z0-9_]*\(/.test(value))) return lhs + value;
  switch (type) {
    case 's':
      return lhs + quote(value);
    case 'n': {
      const n = Number(value);
      if (!Number.isFinite(n)) {
        out.findings.push(warning('terraform.vmware.not-a-number', `${[...path, name].join('.')} is a number; "${value}" was left out.`, { path: [...path, name].join('.') }));
        return null;
      }
      return lhs + String(n);
    }
    case 'b':
      return lhs + (value === 'true' || value === 'yes' ? 'true' : 'false');
    case 'ls':
    case 'ss':
    case 'ln':
    case 'sn': {
      if (value.startsWith('[')) return lhs + indentRaw(value, indent);
      const items = value.split(/[,\n]/).map((s) => s.trim()).filter(Boolean);
      const numeric = type === 'ln' || type === 'sn';
      const rendered = items.map((s) => (isExpression(s) ? s : numeric && Number.isFinite(Number(s)) ? String(Number(s)) : quote(s)));
      return `${lhs}[${rendered.join(', ')}]`;
    }
    case 'm': {
      if (value.startsWith('{')) return lhs + indentRaw(value, indent);
      const pairs = value
        .split('\n')
        .map((line) => /^\s*("?)([^="]+)\1\s*[=:]\s*(.*?)\s*$/.exec(line))
        .filter((m)                       => m !== null);
      if (pairs.length === 0) return null;
      const body = pairs.map((m) => {
        const v = (m[3] ?? '').replace(/^"(.*)"$/, '$1');
        return `${indent}  ${hclKey((m[2] ?? '').trim())} = ${isExpression(v) ? v : quote(v)}`;
      });
      return `${lhs}{\n${body.join('\n')}\n${indent}}`;
    }
    default:
      return lhs + indentRaw(value, indent);
  }
}

function renderBlockBody(
  block             ,
  values                 ,
  path                   ,
  indent        ,
  out         ,
  rules                = {},
  varPath                    = path,
)           {
  const lines           = [];
  const attrs           = [];
  for (const row of block.a) {
    const line = renderAttr(row, values[`r.${[...path, row[0]].join('.')}`], varPath, indent, out);
    if (line !== null) attrs.push(line);
  }
  // Align the `=` of single-line attributes, as terraform fmt does.
  const width = attrs.reduce((w, l) => (l.includes('\n') ? w : Math.max(w, l.indexOf(' = '))), 0);
  for (const l of attrs) {
    const at = l.indexOf(' = ');
    lines.push(!l.includes('\n') && at > 0 ? l.slice(0, at).padEnd(width) + l.slice(at) : l);
  }
  for (const [name, mode, min, max, child] of block.b ?? []) {
    const childPath = [...path, name];
    const toggle = values[`b.${childPath.join('.')}`];
    const included = min >= 1 || rules.minBlocks?.[childPath.join('.')] !== undefined || toggle === true || toggle === 'true';
    if (!included) continue;
    const repeatable = mode !== 1 && max !== 1;
    // The provider checks some minimums in code rather than in its schema.
    const copies = Math.max(1, rules.minBlocks?.[childPath.join('.')] ?? 1);
    for (let k = 0; k < copies; k++) {
      if (lines.length > 0) lines.push('');
      if (k === 0 && repeatable) {
        lines.push(
          copies > 1
            ? `${indent}# ${name}: at least ${copies} are required. Each copy below needs its own values.`
            : `${indent}# ${name}: repeat this block for each one you need.`,
        );
      }
      const childVarPath = k === 0 ? [...varPath, name] : [...varPath, `${name}${k + 1}`];
      lines.push(`${indent}${name} {`);
      lines.push(...renderBlockBody(child, values, childPath, `${indent}  `, out, rules, childVarPath));
      lines.push(`${indent}}`);
    }
  }
  return lines;
}

function providerBlock(provider                , values                 , out         )         {
  const meta = PROVIDER_META[provider];
  if (meta.custom) return meta.custom.render(values, out);
  const lines           = [];
  const credentialAttrs = new Set(meta.credentials.map((c) => c.attr));
  for (const row of info(provider).provider.a) {
    const [name, , flags] = row;
    if (credentialAttrs.has(name) || flags.includes('s') || /password|token|secret|_key$|client_auth_key/.test(name)) continue;
    const line = renderAttr(row, values[`p.${name}`], [], '  ', out);
    if (line !== null) lines.push(line);
  }
  for (const c of meta.credentials) {
    if (c.when && String(values[`p.${c.when}`] ?? '').trim() === '') continue;
    lines.push(`  ${c.attr} = var.${c.variable}`);
    out.variables.set(c.variable, { type: 'string', sensitive: c.sensitive, description: c.description });
  }
  const width = lines.reduce((w, l) => Math.max(w, l.indexOf(' = ')), 0);
  const aligned = lines.map((l) => {
    const at = l.indexOf(' = ');
    return l.includes('\n') || at < 0 ? l : l.slice(0, at).padEnd(width) + l.slice(at);
  });
  // A provider with nothing to configure (random, local, null) needs no block.
  if (aligned.length === 0) return '';
  return `provider "${provider}" {\n${aligned.join('\n')}\n}`;
}

function variablesHcl(variables                      )           {
  return [...variables].map(([name, v]) => {
    const body = [`  type        = ${v.type}`, `  description = ${quote(v.description.split('. ')[0]?.replace(/\.$/, '') ?? name)}`];
    if (v.sensitive) body.push('  sensitive   = true');
    return `variable "${name}" {\n${body.join('\n')}\n}`;
  });
}

/**
 * The Terraform block, provider blocks and variables, around the given
 * resource blocks. A scenario that uses several providers — a key from `tls`,
 * a file from `local`, a run over SSH from `null` — names them all.
 */
export function wrapConfiguration(
  providers                                            ,
  values                 ,
  resources                   ,
  out          = newEmitted(),
)         {
  const list = [...new Set(typeof providers === 'string' ? [providers] : providers)];
  const required = list
    .map(
      (p) => `    ${p} = {
      source  = "${info(p).source}"
      version = "${versionConstraint(p)}"
    }`,
    )
    .join('\n');
  const parts = [
    `terraform {
  required_version = ">= 1.5.0"
  required_providers {
${required}
  }
}`,
    ...list.map((p) => providerBlock(p, values, out)),
    ...resources,
    ...variablesHcl(out.variables),
  ].filter((part) => part.trim() !== '');
  return `${parts.join('\n\n')}\n`;
}

/** A Terraform identifier from whatever name the page was given. */
function localName(name        )         {
  const id = name.trim().toLowerCase().replace(/[^a-z0-9_]+/g, '_').replace(/^_+|_+$/g, '');
  if (id === '') return 'this';
  return /^[a-z_]/.test(id) ? id : `r_${id}`;
}

// ----------------------------------------------------------------- rules ---

/**
 * What the providers check in code rather than in their schemas, so
 * `terraform providers schema` cannot say it and `terraform validate` can.
 * Found by running tools/validate-terraform-blueprints.mjs over every resource
 * with nothing filled in; a new entry is a new failure there.
 */
                         
                                                                                                                
                                                  
                                                                                
                                                  
                                                                              
                                                        
                                                               
                                                                 
 

/** The rules for a resource: the hand-found ones, then those tools/discover-resource-rules.mjs found. */
function rulesFor(type        )                {
  const hand = RESOURCE_RULES[type];
  const found = (DISCOVERED_RULES                                           )[type];
  if (!hand || !found) return hand ?? found ?? {};
  return {
    oneOf: [...(hand.oneOf ?? []), ...(found.oneOf ?? [])],
    allOf: [...(hand.allOf ?? []), ...(found.allOf ?? [])],
    minBlocks: { ...(found.minBlocks ?? {}), ...(hand.minBlocks ?? {}) },
    defaults: { ...(found.defaults ?? {}), ...(hand.defaults ?? {}) },
  };
}

/** Whether a dotted path names a nested block (rather than an argument) in a schema. */
function isBlockPath(schema             , path        )          {
  let block                          = schema;
  const parts = path.split('.');
  for (const [i, part] of parts.entries()) {
    const row                       = block?.b?.find((b) => b[0] === part);
    if (!row) return false;
    if (i === parts.length - 1) return true;
    block = row[4];
  }
  return false;
}

const RESOURCE_RULES                                          = {
  vsphere_network_protocol_profile: { oneOf: [['ipv4', 'ipv6']] },
  vcf_cluster: { minBlocks: { host: 2 } },
  vcf_domain: { minBlocks: { 'cluster.host': 2 } },
  vcf_network_pool: { minBlocks: { network: 1 } },
  nsxt_policy_ipsec_vpn_service: { oneOf: [['gateway_path', 'locale_service_path']] },
  nsxt_policy_cluster_security_config: { oneOf: [['dfw_enabled']] },
  nsxt_policy_gateway_security_config: { oneOf: [['tier1_id', 'tier0_id']] },
  nsxt_compute_manager: { defaults: { 'b.credential.username_password_login': true } },
  vra_cloud_account_vsphere: { oneOf: [['enabled_regions', 'regions']] },
  vra_content_sharing_policy: { oneOf: [['project_id', 'entitlement_type'], ['catalog_source_ids', 'catalog_item_ids']] },
  vcd_api_token: { defaults: { 'r.allow_token_file': 'true' } },
  vcd_catalog_media: { oneOf: [['catalog_id', 'catalog']] },
  vcd_edgegateway_settings: { oneOf: [['edge_gateway_id', 'edge_gateway_name']] },
  vcd_external_network_v2: { defaults: { 'b.nsxt_network': true } },
  vcd_multisite_org_association: { oneOf: [['association_data_file', 'association_data']] },
  vcd_multisite_site_association: { oneOf: [['association_data_file', 'association_data']] },
  vcd_nsxt_network_imported: { oneOf: [['nsxt_logical_switch_name', 'dvpg_name']] },
  vcd_org_oidc: { oneOf: [['wellknown_endpoint', 'access_token_endpoint'], ['wellknown_endpoint', 'user_authorization_endpoint'], ['wellknown_endpoint', 'userinfo_endpoint'], ['wellknown_endpoint', 'issuer_id']] },
  vcd_org_saml: { oneOf: [['identity_provider_metadata_file', 'identity_provider_metadata_text']] },
  vcd_rde: { oneOf: [['input_entity', 'input_entity_url']] },
  vcd_rde_interface_behavior: { oneOf: [['execution', 'execution_json']] },
  vcd_rde_type: { oneOf: [['schema_url', 'schema']] },
  vcd_rde_type_behavior: { oneOf: [['execution', 'execution_json']] },
  vcd_vapp_network: { oneOf: [['prefix_length', 'netmask']] },
  vcd_vm_placement_policy: { oneOf: [['vm_group_ids', 'logical_vm_group_ids']] },
  tls_cert_request: { oneOf: [['private_key_pem']] },
  tls_self_signed_cert: { oneOf: [['private_key_pem']] },
  tls_locally_signed_cert: { oneOf: [['ca_private_key_pem']] },
  local_file: { oneOf: [['content', 'sensitive_content', 'content_base64', 'source']] },
  local_sensitive_file: { oneOf: [['content', 'content_base64', 'source']] },
  cloudinit_config: { minBlocks: { part: 1 } },
  // Cloud rules whose messages no pattern in tools/discover-resource-rules.mjs reads.
  aws_securityhub_standards_control_association: { defaults: { 'r.association_status': 'ENABLED' } },
  aws_cloudwatch_log_delivery_destination: { defaults: { 'b.delivery_destination_configuration': true } },
  aws_odb_cloud_vm_cluster: { oneOf: [['odb_network_id', 'odb_network_arn'], ['cloud_exadata_infrastructure_id', 'cloud_exadata_infrastructure_arn']] },
};

// ------------------------------------------------------------- blueprint ---

                        
                                             
                               
                                     
 

/** The form and the build for one resource, once its schema is in memory. */
function materialize(type        , schema                )               {
  const provider = providerOf(type);
  const rules = rulesFor(type);
  const collected                   = [];
  blockInputs(schema, [], undefined, undefined, collected);
  const inputs                   = collected.map((input) => {
    const path = input.id.slice(2);
    const group = rules.oneOf?.find((g) => g.includes(path));
    // A block the provider always needs starts ticked, so its fields show.
    const forced = input.id.startsWith('b.') && (rules.minBlocks?.[path] !== undefined || rules.oneOf?.some((g) => g[0] === path));
    const preset = rules.defaults?.[input.id] ?? (forced ? true : undefined);
    return {
      ...input,
      ...(preset !== undefined ? { default: preset } : {}),
      ...(group && group.length > 1 ? { hint: `${input.hint ?? ''} · set this or ${group.filter((g) => g !== path).join(' / ')}` } : {}),
    };
  });
  inputs.push(...providerInputs(provider));
  const required = schema.a.filter((a) => a[2].startsWith('r')).length;
  const optional = schema.a.length - required;
  const blocks = (schema.b ?? []).length;
  const { source, version } = info(provider);
  return {
    inputs,
    description:
      `One ${type} resource, with every argument the ${source} ${version} provider takes: ` +
      `${required} required up top, ${optional} optional${blocks > 0 ? `, and ${blocks} nested block${blocks === 1 ? '' : 's'}` : ''} in the sections below. ` +
      'Any field takes a reference — data.x.y.id, var.x — as well as a value.',
    build: (values                 , name        ) => {
      const out          = { variables: new Map(), findings: [] };
      const filled                                          = { ...values };
      // A "one of these" group with none set: the first becomes a variable, so
      // the file validates and the variable's name says what to supply.
      for (const group of rules.oneOf ?? []) {
        const isBlock = (path        )          => isBlockPath(schema, path);
        const set = (path        )          =>
          isBlock(path) ? values[`b.${path}`] === true || values[`b.${path}`] === 'true' : String(values[`r.${path}`] ?? '').trim() !== '';
        if (group.some(set)) continue;
        const first = group[0]          ;
        if (isBlock(first)) filled[`b.${first}`] = true;
        else filled[`r.${first}`] = `var.${variableName(first.split('.'))}`;
      }
      // A "set together" group with one member set: the rest become variables.
      for (const group of rules.allOf ?? []) {
        const given = (path        )          => String(filled[`r.${path}`] ?? '').trim() !== '';
        if (!group.some(given)) continue;
        for (const path of group) if (!given(path) && !isBlockPath(schema, path)) filled[`r.${path}`] = `var.${variableName(path.split('.'))}`;
      }
      const body = renderBlockBody(schema, filled, [], '  ', out, rules);
      const resource = body.length > 0 ? `resource "${type}" "${localName(name)}" {\n${body.join('\n')}\n}` : `resource "${type}" "${localName(name)}" {}`;
      return { files: { 'main.tf': wrapConfiguration(provider, values, [resource], out) }, findings: out.findings };
    },
  };
}

/**
 * The blueprint for one resource: every argument it takes, as a field.
 * `prefix` keeps ids unique where two platforms offer the same resource —
 * tls_private_key is on Linux (lnx_) and Windows (win_) alike.
 *
 * A cloud resource's schema is not in memory until it is picked, so its
 * blueprint is lazy: `load()` fetches the schema file, and until then the
 * form is empty and the description says what is coming.
 */
export function resourceBlueprint(type        , prefix = 'vmw')            {
  const provider = providerOf(type);
  if (!resourceTypes(provider).includes(type)) throw new Error(`${type}: not in the provider schema data`);
  const bare = type.slice(provider.length + 1);
  // NSX's policy API is the current one; "Policy" on 170 labels says nothing.
  const human = humanize(provider === 'avi' ? aviWords(bare) : provider === 'nsxt' ? bare.replace(/^policy_/, '') : bare);
  let made                          ;
  const ready = ()                           => {
    if (made) return made;
    const schema = resourceSchema(type);
    if (schema) made = materialize(type, schema);
    return made;
  };
  const blueprint = {
    id: `${prefix}_${type}`,
    label: `${human} (${type})`,
    group: sectionOf(provider, type),
    emits: [type],
    get inputs()                            {
      return ready()?.inputs ?? [];
    },
    get description()         {
      return ready()?.description ?? `One ${type} resource, with every argument the ${info(provider).source} provider takes. Loading its schema…`;
    },
    build: (values                 , name        ) => {
      const m = ready();
      if (!m) throw new Error(`${type}: its schema has not loaded yet`);
      return m.build(values, name);
    },
  };
  // Added, not spread in: a spread would read the getters once, while empty.
  if (isCloud(provider)) Object.defineProperty(blueprint, 'load', { enumerable: true, value: () => loadResource(type) });
  else ready();
  return blueprint             ;
}

/** Every resource of a provider, as blueprints, in section then name order. */
export function providerBlueprints(provider                , prefix = 'vmw')              {
  const types = resourceTypes(provider);
  const rank = (type        )         => {
    const section = sectionOf(provider, type);
    // Beta and deprecated resources last, so the supported ones are found first.
    return /Deprecated/.test(section) ? 2 : /Beta/.test(section) ? 1 : 0;
  };
  return types
    .map((type) => ({ type, section: sectionOf(provider, type) }))
    .sort((a, b) => rank(a.type) - rank(b.type) || a.section.localeCompare(b.section) || a.type.localeCompare(b.type))
    .map(({ type }) => resourceBlueprint(type, prefix));
}

export const VMWARE_PROVIDERS                            = ['vsphere', 'vcf', 'nsxt', 'avi', 'vra', 'vcd'];
